/**
 * Synthetic complaint scenarios used to stress the interview engine.
 *
 * Each scenario is a patient who answers whatever they are asked, drawing from
 * `replies` in order. That is deliberately crude: it simulates a patient who is
 * *not* reading the question carefully, which is exactly the case where a badly
 * ordered or repetitive interview shows up. Scenarios with `answerFor` model a
 * cooperative patient instead, keyed by slot.
 */

export interface Scenario {
  id: string;
  /** What the engine should route this to. */
  expectPathway: "rash" | "lesion" | "acne" | "hair_loss" | "general";
  opening: string;
  /** Slot-keyed answers. Anything unmapped falls through to `fallback`. */
  answerFor: Record<string, string>;
  fallback?: string;
  /** Notes for the reviewer about what this case is probing. */
  probes: string;
}

